document.querySelectorAll(".burger").forEach(e=>{e.addEventListener("click",()=>{let e=document.querySelector(".nav");if(!e)return;let l="flex"===e.style.display;e.style.display=l?"":"flex",e.style.flexDirection="column",e.style.position="absolute",e.style.top="100%",e.style.right="1rem",e.style.background="#fff",e.style.padding="1rem",e.style.borderRadius="0.75rem",e.style.boxShadow="0 4px 12px rgba(0,0,0,0.08)"})});